def demo_path(name, base="nbs/data", reset=True):
    'Return a scratch path under `base`, optionally removing any previous artifact.'
    path = Path(base) / name
    if reset: remove_demo_path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


